// sourceIDNAJoiningType retains the L/R/D/T classes consumed by Source CONTEXTJ.
// Other classes are equivalent to no matching contextual class and return zero.
func sourceIDNAJoiningType(value rune) byte {
	index := sort.Search(len(sourceIDNAJoiningIntervals), func(index int) bool { return sourceIDNAJoiningIntervals[index].last >= value })
	if index < len(sourceIDNAJoiningIntervals) && sourceIDNAJoiningIntervals[index].first <= value {
		return sourceIDNAJoiningIntervals[index].kind
	}
	return 0
}

